                draftText: "يقع المسجد الأقصى المبارك على هضبة الحرم القدسي الشريف في الزاوية الجنوبية الشرقية من البلدة القديمة للقدس، على مساحة تبلغ نحو 144 دونماً. هذه الهضبة ليست مجرد قطعة أرض مرتفعة، بل هي قلب فلسطين الجيولوجي والروحي. اختيار هذا الموقع للعبادة لم يكن اعتباطياً؛ فالتضاريس الطبيعية جعلت منه نقطة دفاعية مطلة على وادي قدرون شرقاً ووادي جهنم جنوباً، مما أعطاه قدسية استراتيجية قبل أن يكون دينية.",
