                title: "ما قبل الإسلام: قدسية متجذرة",
                draftText: "الرواية الفلسطينية لا تبدأ من الفتح الإسلامي فقط، بل تمتد إلى جذور المكان. يُعتقد أن الموقع كان معبداً كنعانياً قديماً، وهو أمر منطقي لمدينة قدسية اسمها \"أور سالم\" (مدينة السلام) أسسها اليبوسيون الكنعانيون. ثم شيد النبي سليمان هيكله هنا (القرن العاشر ق.م)، وأعاد بناؤه اليهود بعد السبي، ثم وسّعه هيرودس الأدومي (القرن الأول ق.م) بشكل هائل. دمر الرومان الهيكل عام 70م، وأقاموا معبداً لجوبيتر فوق أنقاضه. هذه الطبقات المتعاقبة تؤكد أن قدسية المكان سابقة لكل الأديان، وأن كل قادم جديد بنى على ما سبقه، دون أن يلغي حق من سبقه. وهنا ترفض الرواية الفلسطينية الرواية الإسرائيلية التي تزعم وجود الهيكل تحت الأقصى وتطالب بهدمه؛ فالآثار الموجودة تحت الحرم هي آثار رومانية وبيزنطية وإسلامية، والهيكل -إن وُجد- فهو طبقة أثرية من طبقات عديدة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lmsjd-l-qs-lmbrk-lhrm-lqdsy-lshryf-4aeec5-section-3",
                title: "الفتح الإسلامي: عهد عمر بن الخطاب",
                draftText: "في عام 15هـ/636م، تسلم الخليفة عمر بن الخطاب مفاتيح القدس صلحاً من بطريركها صفرونيوس، بعد حصار لم يسفك فيه دماء. العهدة العمرية هي الوثيقة التأسيسية للوجود الإسلامي في القدس؛ تضمن للمسيحيين كنائسهم وأمنهم مقابل الجزية. تروي الرواية الفلسطينية أن عمر رفض الصلاة في كنيسة القيامة حين أدركه وقت الصلاة، خشية أن يتخذها المسلمون مسجداً من بعده. هذا الفعل النبيل هو الذي جعل الأقصى يُبنى في موقعه الحالي؛ فأراد عمر أن يكون للمسلمين مسجدهم المستقل. توجه إلى الهضبة المهملة التي كانت مكباً للنفايات الرومانية، ونظفها بنفسه، وبنى في طرفها الجنوبي مسجداً خشبياً يتسع لثلاثة آلاف مصلٍّ. هنا تبدأ الرواية الإسلامية الفلسطينية للمكان: ربطه بالمعراج النبوي، وتطهيره من الإهمال الروماني.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
