                title: "العصر الأموي: البناء التأسيسي",
                draftText: "الخليفة عبد الملك بن مروان وابنه الوليد هم من أعطوا الحرم شكله المعماري الخالد. بنى عبد الملك قبة الصخرة (72هـ/691م) فوق الصخرة التي يُعتقد أن النبي محمداً عرج منها إلى السماء. القبة ليست مسجداً للصلاة بل مشهداً تذكارياً، بُني ليكون تحفة معمارية تنافس الكنائس البيزنطية. قطر قبتها 20 متراً وارتفاعها 35 متراً، وزُينت بالفسيفساء والرخام والآيات القرآنية. أما ابنه الوليد فبنى المسجد القبلي (المصلى الرئيسي) في جنوب الحرم، وجعله مسجداً جامعاً. وثيقة تاريخية نادرة عُثر عليها في خرائب المسجد القبلي تعود للعصر الأموي تذكر اسم بانيه وأرخ بنائه. (مصدر: كتاب \"تاريخ المسجد الأقصى\" – د. عبد الله معروف).",
                status: ContentReviewStatus.sourceReview,
