                draftText: "مرت على الأقصى فترات عصيبة. الزلازل المتتالية (خاصة زلزال 746م و1033م) دمرت أجزاء كبيرة من المسجد القبلي. الخلفاء الفاطميون، وخاصة الظاهر لإعزاز دين الله، أعادوا بناء المسجد القبلي بشكله الحالي تقريباً سنة 1035م، وقلصوا عرضه وطولوا رواقه الأوسط ليكون صحناً مكشوفاً. هذه الفترة شهدت أيضاً الاستيطان الصليبي.",
