                title: "الأيوبيون والمماليك: استرداد وتجديد",
                draftText: "حين حرر صلاح الدين الأيوبي القدس عام 1187م، كان الصليبيون قد حولوا المسجد الأقصى إلى قصر وإسطبلات، وقبة الصخرة إلى كنيسة (Templum Domini). أول ما فعله صلاح الدين هو تطهير الحرم بالماء والطيب، وإزالة الصلبان، وإعادة المحراب إلى اتجاهه الصحيح نحو مكة، ونصب المنبر الخشبي الرائع الذي حمله خصيصاً من حلب (منبر نور الدين زنكي). هذا المنبر، الذي احترقه متطرف يهودي عام 1969، كان تحفة فنية من آلاف القطع الخشبية المتشابكة دون مسمار واحد، ويمثل ذروة الفن الخشبي الإسلامي.\n\nالمماليك هم أكثر من ترك بصماته المعمارية على الحرم. أضافوا الأروقة الحجرية المحيطة بقبة الصخرة، والمآذن، والمدارس (كالمدرسة الأشرفية قبالة المسجد القبلي)، والأسبلة، وقباباً متعددة (قبة النحوية، قبة موسى، قبة الأرواح). (مصدر: \"تاريخ القدس\" – مجير الدين الحنبلي، تحقيق د. عبد الله عطيات).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
