      HistoricalNarrativeSection(
                id: "lmsjd-l-qs-lmbrk-lhrm-lqdsy-lshryf-4aeec5-section-7",
                title: "العصر العثماني: الإدارة والترميم",
                draftText: "أولى السلاطين العثمانيون، بدءاً من سليم الأول ثم سليمان القانوني، الحرم اهتماماً كبيراً. سليمان القانوني هو من جدد الفسيفساء الخارجية لقبة الصخرة، وأضاف الكاشان (البلاطات الخزفية) الفارسي، وبنى سور القدس الحالي. أنشأ نظاماً وقفياً دقيقاً لإدارة الحرم من خلال دار الأيتام (التكية) وعدة أوقاف عقارية. سجلات المحكمة الشرعية في القدس تحوي آلاف الوثائق عن تعيينات \"خدام الحرم\" و\"البوابين\" و\"المؤذنين\"، وعن رواتبهم ومخصصاتهم، مما يدل على مؤسسة دينية واجتماعية ضخمة. (مصدر: سجلات محكمة القدس الشرعية، أرشيف دار الوثائق).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lmsjd-l-qs-lmbrk-lhrm-lqdsy-lshryf-4aeec5-section-8",
                title: "العصر الحديث: الاحتلال والمقاومة الشعبية",
                draftText: "لا تكتمل الرواية الفلسطينية دون ذكر النكبة عام 1948 وما تلاها. احتلت إسرائيل القدس الشرقية عام 1967، وفرضت سيطرتها على الحرم القدسي. محاولة إحراق المسجد القبلي عام 1969 على يد متطرف أسترالي يهودي كانت صدمة للمسلمين جميعاً. ومنذ ذلك الحين، والمسجد الأقصى يتعرض لاقتحامات المستوطنين المتكررة بحماية الجيش الإسرائيلي، ومحاولات تقسيمه زمانياً ومكانياً.\n\nالرواية الفلسطينية هنا تنتقل من التاريخ إلى الحاضر الحي. المرابطون والمرابطات في الأقصى، وهم رجال ونساء فلسطينيون من القدس والداخل المحتل، يتولون حراسة المسجد والرباط فيه ليل نهار لمنع المستوطنين من تدنيسه. هم امتداد لخدام الحرم عبر القرون. انتفاضة البوابات الإلكترونية عام 2017، حين انتفض المقدسيون رفضاً لتركيب بوابات إلكترونية على مداخل الأقصى، وأقاموا الصلاة في الشوارع أياماً حتى أزيلت، هي ملحمة بطولية معاصرة تؤكد أن الأقصى لا يُدار بقرارات خارجية، بل بإرادة الشعب الفلسطيني. (مصادر: أرشيف وكالة وفا، مركز القدس للحقوق الاجتماعية والاقتصادية).",
