                draftText: "المسجد الأقصى المبارك ليس مجرد بناء حجري، بل هو هوية فلسطينية متجسدة. من تطهير عمر بن الخطاب للمكان، إلى بناء الأمويين لقبة الصخرة، إلى تجديد المماليك لأروقته، إلى رباط المرابطين اليوم، المكان هو شاهد على ارتباط الشعب الفلسطيني بأرضه ودفاعه عن مقدساته عبر أربعة عشر قرناً.",
