                draftText: "حائط البراق هو جزء مكشوف من السور الغربي الضخم للحرم القدسي الشريف، يبلغ طوله حوالي 48 متراً وارتفاعه 18 متراً. بُني هذا السور كجزء من مشروع توسعة هيرودس الكبير للحرم في القرن الأول ق.م، لكنه ليس بناءً يهودياً خالصاً كما تروج الرواية الإسرائيلية؛ فالمهندسون الذين بنوه كانوا فينيقيين وروماناً، والحجارة قطعت بأيدٍ كنعانية محلية. الجدار هو مجرد جدار استنادي ضخم الغرض منه رفع مستوى أرض الحرم لتكون منبسطة، وليس له أي قدسية دينية يهودية في أصله.",
