                draftText: "سوق القطانين (سوق تجار القطن) هو أحد أجمل الأسواق التاريخية في القدس. يقع في قلب البلدة القديمة، ويمتد من جهة الشمال إلى بوابة ضخمة تفتح مباشرة على ساحات الحرم القدسي الشريف (باب القطانين). السوق مسقوف بأقبية حجرية متقاطعة، وفي وسطه حمام تقليدي (حمام العين). النوافذ العلوية تسمح بدخول أشعة الشمس بشكل درامي يبرز جمال الحجر. الرواية المحلية ترى فيه تحفة معمارية تجمع بين الوظيفة التجارية والجمالية.",
