                draftText: "بناه الأمير المملوكي تنكز الناصري نائب الشام في عهد السلطان الناصر محمد بن قلاوون عام 1336م. كان تنكز محباً للعمران، وبنى عدة مشاريع في القدس. السوق لم يكن مجرد مكان لبيع القطن، بل كان جزءاً من وقف كبير يخصص ريعه للمدرسة التنكزية ودار الحديث القريبتين. هذا التكامل بين السوق والمدرسة والمسجد هو نموذج للمدينة الإسلامية حيث العبادة والعلم والتجارة في نسيج واحد.",
