                title: "الحكاية الاقتصادية",
                draftText: "القطن كان محصولاً استراتيجياً في فلسطين المملوكية، يُزرع في غور الأردن ويُباع في أسواق القدس قبل تصديره إلى أوروبا عبر موانئ غزة ويافا. سوق القطانين كان مركز هذه التجارة. وثائق المحكمة الشرعية تذكر تجار القطن من العائلات المقدسية والخليلية والنابلسية، وتوضح كيف كان السوق مكاناً للقاء والتبادل التجاري بين فلسطين والعالم.",
