                draftText: "عند سفح جبل الزيتون الشرقي، في عمق وادي قدرون، تقع كنيسة قبر السيدة مريم. للوصول إليها، ينزل الزائر 47 درجة حجرية إلى سرداب تحت الأرض، وكأنه يهبط إلى أحشاء الأرض ليقابل سراً مخبأ. المكان ليس كنيسة مرتفعة شاهقة، بل مغارة متواضعة. هذا التواضع المعماري يعكس شخصية صاحبة المكان: العذراء مريم، الأم المتواضعة التي عاشت وماتت في هدوء بعيداً عن الأضواء. الرواية الفلسطينية المحلية تحب هذا المكان بالذات لأنه يذكر الفلاحين ببيوتهم المتواضعة المنحوتة في الصخر.",
