                draftText: "بحسب التقاليد المسيحية الشرقية التي يتبناها مسيحيو فلسطين، عاشت مريم بعد صلب ابنها في رعاية يوحنا الحبيب في القدس، وماتت هناك. دُفنت في هذه المغارة في وادي قدرون من قبل الرسل. بعد ثلاثة أيام، فُتح القبر فلم يُعثر على جسدها، بل ورداً وريحاناً، مما يؤكد صعودها إلى السماء بالنفس والجسد (عيد الرقاد). هذه الرواية الشرقية تختلف قليلاً عن الرواية الكاثوليكية التي تذكر انتقالها من أفسس، لكنها متجذرة في التربة المقدسية.",
