                draftText: "بُنيت أول كنيسة فوق المغارة في القرن الخامس الميلادي، خلال العصر البيزنطي، بشكل دائري فوق القبر. دمرها الفرس ثم أعاد الصليبيون بناءها بشكلها الحالي في القرن 12، مع درج النزول الطويل والواجهة الحجرية الجميلة. دُفن فيها ملوك صليبيون مثل بلدوين الثاني ومليساندا، مما أضفى عليها أهمية سياسية أيضاً. بعد صلاح الدين، لم تتعرض الكنيسة لتدمير، واستمرت مقصداً للحجاج المسيحيين والمسلمين على السواء؛ فالعذراء مريم مكرمة في القرآن أيضاً بصفتها السيدة الطاهرة.",
