                draftText: "في الرواية الفلسطينية الشفوية، تُعرف المغارة ببساطة بـ\"قبر مريم\". النساء المقدسيات المسيحيات والمسلمات كن يزرن المكان للتبرك وطلب الشفاعة، خاصةً في أمور الحمل والولادة. هذه الممارسة الشعبية تجعل من مريم شخصية حية في الوجدان الفلسطيني، وليست مجرد أثر تاريخي. الموقع اليوم تحت رعاية بطريركية الروم الأرثوذكس والأرمن، وتُقام فيه الصلوات يومياً.",
