                title: "خلاصة الرواية",
                draftText: "قبر السيدة مريم هو أكثر الأماكن حميمية في القدس. إنه لا يروي قصة لاهوتية مجردة، بل قصة أم ودّعت الحياة بين أحبائها. الرواية الفلسطينية تجعله مكاناً للتعزية والتواصل الإنساني مع المقدس، بعيداً عن تعقيدات اللاهوت.\n\n(المصادر: \"دليل الأماكن المقدسة\" – مطرانية الروم الأرثوذكس، \"مريم في التراث الفلسطيني\" – د. فيرا سمعان).",
