                draftText: "المدرسة الطشتمرية: بناها الأمير المملوكي طشتمر العلائي عام 1382م. واجهتها الحجرية المشذبة بخطوط حمراء وبيضاء (الأبلق) تلفت الأنظار. كانت المدرسة تدرس الفقه الشافعي، وأوقفت عليها حوانيت في السوق المجاور لضمان استمراريتها المالية.\n\nدار الحديث التنكزية: بناها الأمير تنكز الناصري عام 1328م. كانت متخصصة في تعليم الحديث النبوي. مدخلها الضخم وبوابتها النحاسية المزخرفة تدل على أهميتها. الرواية المحلية تروي أن طلاب العلم كانوا يأتونها من كل أنحاء العالم الإسلامي.\n\nخانقاه صلاح الدين: بناها صلاح الدين الأيوبي لكن المماليك وسعوها. كانت مركزاً للمتصوفة الذين ينقطعون للعبادة بجوار الأقصى.",
