                draftText: "تقع القلعة قرب باب الخليل (باب يافا)، عند أعلى نقطة في البلدة القديمة للقدس. اسمها العربي الشائع \"قلعة القدس\"، لكنها تُعرف خطأً باسم \"برج داود\". هذه التسمية لا علاقة لها بالنبي داود، بل هي من اختراع الصليبيين في القرن 12م، الذين ظنوا أن أحد أبراجها هو برج النبي داود المذكور في المزامير. الرواية الفلسطينية تصحح: لا أثر للنبي داود هنا، والقلعة هي بناء روماني-أيوبي-مملوكي-عثماني تراكمي. استخدام الاسم \"برج داود\" اليوم هو جزء من محاولة تهويد المكان وربطه قسراً بالتاريخ اليهودي، في حين أن الاسم العربي الأصيل هو \"القلعة\" فقط. (مصدر: \"قلاع فلسطين\" – د. يوسف النتشة، مطبوعات رواق).",
