                title: "الجذور: هيرودس والرومان",
                draftText: "الموقع الاستراتيجي كان معروفاً منذ القدم. بنى الملك هيرودس الكبير (القرن الأول ق.م) قصراً محصناً هنا أسماه \"قصر هيرودس\"، بأبراج ثلاثة أطلق عليها أسماء أحبائه: فصائيل (أخيه)، وهيبيكوس (صديقه)، ومريمان (زوجته التي قتلها). دمر الرومان المدينة عام 70م، لكنهم أبقوا على الأبراج لتكون حصناً للكتيبة الرومانية العاشرة (Legio X Fretensis) التي حكمت القدس المدمرة. أساسات هذه الأبراج لا تزال موجودة في القلعة الحالية، خاصةً قاعدة \"برج فصائيل\" الضخمة التي تُعتبر قلب القلعة.",
