                draftText: "الشكل المعماري الحالي للقلعة يعود بشكل رئيسي للعصر المملوكي. بعد تحرير عكا وطرد الصليبيين نهائياً (1291م)، اهتم المماليك بتحصين المدن الداخلية خوفاً من غزوات المغول. السلطان الناصر محمد بن قلاوون (القرن 14) هو من بنى معظم الجدران والأبراج والخنادق التي نراها اليوم. أضاف مسجداً داخل القلعة، وحولها إلى ثكنة عسكرية وسجن للأسرى. الرواية الفلسطينية تحفظ أسماء أمراء مماليك نقشوا أسماءهم على حجارة القلعة، مما يدل على اعتزازهم بدورهم في حماية القدس. (مصدر: \"تاريخ القدس\" – مجير الدين الحنبلي).",
