                title: "الحديث: من معسكر إلى متحف",
                draftText: "في زمن الانتداب البريطاني، خرجت القلعة عن الخدمة العسكرية وتحولت إلى متحف. بعد 1948، سيطر الأردن على القدس الشرقية وجعلها متحفاً للآثار الفلسطينية. بعد 1967، احتلتها إسرائيل وحولتها إلى \"متحف برج داود لتاريخ القدس\". وهنا تبرز الرواية المضادة: المتحف الحالي يقدم سردية تاريخية تركز على التاريخ اليهودي وتهش الوجود العربي الإسلامي. الرواية الفلسطينية تؤكد أن غالبية آثار القلعة هي رومانية وإسلامية، وأن أبرز معالمها (المئذنة) عثماني.",
