                title: "خلاصة الرواية",
                draftText: "القلعة هي حارسة القدس الغربية، بُنيت بأيادٍ رومانية، وحُصنت بأيادٍ أيوبية ومملوكية، وتوجت بمئذنة عثمانية، وهي تشهد على أن الدفاع عن القدس كان ولا يزال مهمة إسلامية فلسطينية.\n\n(مصادر عامة: \"بلادنا فلسطين\" – مصطفى الدباغ، \"دليل أهم معالم القدس\" – مؤسسة إحياء التراث، Riwaq Registry).",
