                title: "الموقع والتأسيس",
                draftText: "تقع كنيسة القيامة في قلب البلدة القديمة للقدس، في الحي المسيحي، على بُعد أمتار من المسجد الأقصى. بُنيت فوق الجلجلة، الموقع الذي يُعتقد أن المسيح صُلب فيه ودُفن وقام من بين الأموات. هذا التداخل بين الصلب والقيامة في مكان واحد هو ما يجعل كنيسة القيامة فريدة بين كنائس العالم؛ فهي ليست مجرد كنيسة، بل محجة تجمع أخطر محطات الآلام والقيامة. الرواية الفلسطينية المسيحية تسميها \"كنيسة القيامة\"، بينما تُعرف في الغرب باسم \"كنيسة القبر المقدس\" (Church of the Holy Sepulchre)، وهو اختلاف في التسمية يعكس اختلافاً في التركيز اللاهوتي؛ فالمسيحيون الفلسطينيون يركزون على القيامة لا الموت.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
