                title: "ما قبل الكنيسة: محجر ومقبرة",
                draftText: "الموقع كان في الأصل محجر حجارة مهملاً خارج أسوار القدس في القرن الأول الميلادي، وكان يُستخدم أيضاً كمقبرة. الأناجيل تذكر أن المسيح صُلب خارج السور في مكان يُدعى \"الجلجلة\" (مكان الجمجمة)، ودُفن في قبر حجري قريب. الرواية الفلسطينية المحلية تروي أن هذه المنطقة كانت أرضاً مكشوفة قاحلة، وأن القبر كان ملكاً ليوسف الرامي، وهو رجل من الرامة (قضاء القدس)، مما يعطي للقصة بعداً فلسطينياً محلياً.",
                status: ContentReviewStatus.sourceReview,
