                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lqym-431ed2-section-3",
                title: "البناء البيزنطي: هيلانة وقسطنطين",
                draftText: "بعد انتصار الإمبراطور قسطنطين على منافسه ليسينيوس (324م)، تبنّى المسيحية ديناً للإمبراطورية. والدته القديسة هيلانة (حوالي 326م) قامت برحلة حج إلى القدس بحثاً عن الصليب. الرواية الكنسية الفلسطينية تروي أن هيلانة، بإرشاد من مسيحيي القدس المحليين، وجدت ثلاثة صلبان في مغارة تحت معبد روماني كان قد بناه هادريان فوق الجلجلة لإخفاء المكان المقدس. للتحقق من الصليب الحقيقي، لمسته بجسد مريض فشُفي، فأمرت بهدم المعبد الروماني وبناء الكنيسة. هذه القصة، بغض النظر عن دقتها التاريخية الكاملة، تؤكد حقيقة أن المسيحيين الفلسطينيين هم من حافظوا على ذاكرة المكان طوال 300 عام بين الصلب والبناء، وهم من أرشدوا هيلانة إليه. هذا عنصر جوهري في الرواية الفلسطينية: استمرارية الوجود المسيحي المحلي.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lqym-431ed2-section-4",
                title: "العمارة الأصلية والتدمير",
                draftText: "الكنيسة الأصلية التي بناها قسطنطين كانت بازيليكا ضخمة تضم ثلاث مناطق: كنيسة الشهادة (مارتيريوم)، وساحة مكشوفة حول الجلجلة، والقبر المقدس داخل قبة مستديرة (الأنسطاسيس). هذه التحفة المعمارية تعرضت للتدمير على يد الفرس الساسانيين عام 614م، ثم أُحرقت بالكامل بأمر الخليفة الفاطمي الحاكم بأمر الله عام 1009م، في واحدة من أحلك فترات العلاقات الإسلامية المسيحية.",
                status: ContentReviewStatus.sourceReview,
