                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lqym-431ed2-section-5",
                title: "إعادة البناء الصليبية والتسامح الأيوبي",
                draftText: "أعاد البيزنطيون بناء الكنيسة جزئياً، لكن التغيير الأكبر حدث مع الصليبيين (القرن 12). قاموا بتوحيد جميع المواقع المقدسة تحت سقف واحد، وأضافوا الأجراس والواجهة الرومانسكية. بعد تحرير القدس على يد صلاح الدين الأيوبي عام 1187م، أُغلقت الكنيسة لفترة وجيزة، لكنه أعاد فتحها أمام الحجاج المسيحيين. الرواية الفلسطينية تفخر بأن صلاح الدين رفض هدم الكنيسة كما طلب بعض مستشاريه، قائلاً: \"لا نُعطيهم ذريعة ليقولوا إنا هدمنا كنائسهم كما هدموا مساجدنا\". بل أكثر من ذلك، أُسندت حراسة الكنيسة لعائلة فلسطينية مسلمة هي عائلة جودة (مفاتيح الكنيسة)، وعائلة نusseibeh (حفظ النظام داخلها)، وهما عائلتان مقدسيتان مسلمتان تتوارثان هذه المهمة حتى اليوم. هذا التقليد الفريد، حيث يسلم مسلم فلسطيني مفتاح أقدس كنيسة في العالم لراهب مسيحي كل صباح، هو أبلغ تعبير عن التعايش الفلسطيني. (مصدر: \"حراس القبر المقدس\" – د. مازن جودة، أرشيف العائلة).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lqym-431ed2-section-6",
                title: "الوضع الراهن والنزاعات",
                draftText: "منذ العصر العثماني، تخضع الكنيسة لـ \"الوضع الراهن\" (Status Quo)، وهو اتفاق معقد بين الطوائف المسيحية (الروم الأرثوذكس، اللاتين الكاثوليك، والأرمن) لتقاسم أجزاء الكنيسة وساعات الصلاة. أي تغيير طفيف يثير نزاعاً. الرواية الفلسطينية المحلية تروي قصة \"السلم الثابت\" الموضوع عند إحدى نوافذ الكنيسة منذ القرن 18؛ لم يحركه أحد لأن أي طائفة تحركه تخرق الوضع الراهن. هذه القصة الطريفة تعكس جموداً إدارياً، لكنها تؤكد أيضاً أن الفلسطينيين، مسلمين ومسيحيين، هم من يضمنون استقرار هذا الموقع المقدس عبر العصور.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
