      HistoricalNarrativeSection(
                id: "knys-lqym-431ed2-section-7",
                title: "خلاصة الرواية",
                draftText: "كنيسة القيامة، في الرواية الفلسطينية، ليست مجرد موقع مسيحي عالمي، بل هي كنيسة فلسطينية محلية. مسيحيو القدس هم من حفظوا ذاكرتها، ومسلمو القدس هم من حمى مفاتيحها. هي شهادة حية على أن فلسطين هي مهد المسيحية الأول، وأن التعايش بين الأديان فيها ليس شعاراً بل ممارسة يومية عمرها ألف عام.\n\n(المصادر: \"تاريخ الكنائس في الأرض المقدسة\" – الأب عيسى مصلح، \"كنيسة القيامة\" – مطرانية الروم الأرثوذكس في القدس، أرشيف عائلة جودة المقدسية).",
