                draftText: "في العصر الأيوبي والمملوكي، تحولت الكنيسة الصليبية في طابقها العلوي إلى مسجد ومقام. أُضيف المحراب، ووُضعت على القبر كسوة خضراء، وأصبح المقام جزءاً من الوقف الإسلامي. السلطان المملوكي المؤيد شيخ هو من قام بأعمال الترميم الكبرى في القرن 15. مجير الدين الحنبلي، مؤرخ القدس المقدسي، يذكره كأحد المقامات المعظمة في المدينة.",
