                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "mqm-lnby-dwwd-jbl-shywn-3a3d36-section-4",
                title: "النزاع الحديث",
                draftText: "بعد نكبة 1948، سيطرت إسرائيل على جبل صهيون، وحولت الطابق السفلي إلى كنيس يهودي (قبر داود المزعوم)، بينما بقي الطابق العلوي مسجداً ومقاماً تحت سيطرة الأوقاف الإسلامية حتى 1967، ثم احتلته إسرائيل وحولته بالكامل. الرواية الفلسطينية ترفض هذا الاستيلاء وتعتبره جزءاً من مخطط تهويد القدس. الحاخامات اليهود أنفسهم منقسمون حول صحة القبر، لكن الاحتلال يستخدمه كأداة سياسية. العائلة الفلسطينية التي كانت ترعى المقام (آل الأنصاري) ما زالت تحتفظ بمفاتيحه القديمة وتطالب بإعادته.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
