      HistoricalNarrativeSection(
                id: "mqm-lnby-dwwd-jbl-shywn-3a3d36-section-5",
                title: "خلاصة الرواية",
                draftText: "مقام النبي داوود هو مثال آخر على صراع الروايات في القدس. بالنسبة للفلسطينيين، هو مقام إسلامي لنبي مكرم، استُولي عليه بقوة الاحتلال. إعادته هي جزء من استعادة الهوية المقدسية المنهوبة.\n\n(المصادر: \"تاريخ القدس\" – مجير الدين الحنبلي، \"المقامات الإسلامية في فلسطين\" – د. يوسف النتشة، مقابلات مع عائلة الأنصاري – مركز العودة).",
