    narrativeSections: <HistoricalNarrativeSection>[
      HistoricalNarrativeSection(
                id: "lhrm-lbrhymy-899e38-section-1",
                title: "ما قبل البناء: قدسية الموقع",
                draftText: "قبل أن يُبنى أي حجر في الحرم الإبراهيمي، كانت الأرض نفسها مقدسة. يُعتقد أن الموقع كان في الأصل معبداً كنعانياً، وهذا ليس انتقاصاً من قدسيته، بل تأكيد على عمق الجذور الروحية للمكان في أرض فلسطين. القصة التوراتية/القرآنية تروي أن النبي إبراهيم اشترى مغارة المكفيلة من عفرون الحثي، وهو رجل كنعاني من سكان البلاد الأصليين، ليدفن فيها زوجته سارة. هذا الفعل الشرائي بالغ الأهمية في الرواية المحلية؛ فهو يُظهر أن العلاقة مع المكان بدأت باحترام العرف والقانون المحلي، لا بالغزو أو الاستيلاء. هذا هو الأساس الذي بنى عليه الفلسطينيون روايتهم: نحن ورثة إبراهيم، ضيف الله، وورثة الحثيين الكنعانيين الذين باعوه الأرض.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lhrm-lbrhymy-899e38-section-2",
                title: "العمارة عبر العصور: تراكم لا إحلال",
                draftText: "البناء الهيرودي الضخم (القرن الأول ق.م) الذي يحيط بالحرم اليوم بسوره الحجري المهيب (بطول 60 متراً وعرض 34 متراً) ليس بناءً يهودياً خالصاً. هيرودس كان أدومياً، عيّنه الرومان ملكاً على المنطقة. بنى هذا السور ليكون ضريحاً يضاهي أضرحة الأباطرة، وليس معبداً يهودياً. هذا التدقيق مهم؛ فالرواية الفلسطينية ترى في هذا السور إرثاً أدومياً رومانياً، استخدمه البيزنطيون لاحقاً لبناء كنيسة كبرى في وسطه.\n\nمع الفتح الإسلامي، لم يهدم المسلمون الكنيسة بالكامل، بل حولوها إلى مسجد، مع إبقاء احترام المكان. في العصر الأيوبي، صلاح الدين الأيوبي، بعد تحرير الخليل من الصليبيين الذين كانوا يمنعون المسلمين من دخوله، أعاد المكان إلى قدسيته الإسلامية. أُضيف المنبر الخشبي البديع (الذي احترق عام 1969)، والمحراب، والمئذنتان. المماليك (الناصر محمد، قايتباي) هم من أضافوا الرواقين الشمالي والجنوبي، والأبواب المزخرفة، والمقامات المغطاة بالكسوة الفاخرة. هذا التطور يثبت أن الحرم الإبراهيمي كما نراه اليوم هو، في شكله المعماري النهائي، عمل فني إسلامي تراكمي.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lhrm-lbrhymy-899e38-section-3",
                title: "المجتمع الخليلي والإدارة الوقفية (القرن 12 – 20)",
                draftText: "هنا يظهر الجانب الاجتماعي الغائب في الروايات الأخرى. منذ العهد الأيوبي، أنشئ للحرم وقف ضخم، يضم أملاكاً وقرى كاملة في محيط الخليل، لضمان استمرارية الصلاة والخدمة فيه. سجلات المحكمة الشرعية في الخليل (وهي كنز معلوماتي لا يُقدّر بثمن) تظهر تفاصيل دقيقة عن وظائف \"خدام الحرم\"، وكيف كانت عائلات مقدسية وخليلية بعينها تتوارث هذه المهام شرفاً. كان هناك \"شيخ الخدام\"، و\"قارئ البخاري\"، و\"السقاة\"، و\"الفرّاشون\". الحرم لم يكن مجرد مسجد، بل مؤسسة اقتصادية واجتماعية تشغل عشرات العائلات وتؤمن لهم رزقهم وتربطهم عضوياً بالمكان. الرواية الشفوية لأهالي الخليل، التي وثّقها د. منذر أبو حمدة، تروي أن المدينة كانت تحتفل بموسم الحرم في شهر رمضان، وتُقام الولائم في ساحاته، وكان المسيحيون يزورونه تبركاً أيضاً. (مصدر: سجلات محكمة الخليل الشرعية، أرشيف دار الوثائق في القدس).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lhrm-lbrhymy-899e38-section-4",
                title: "النزاع الحديث وثبات الهوية",
                draftText: "لا يمكن كتابة رواية الحرم الإبراهيمي المعاصرة دون التطرق لمجزرة 1994 التي ارتكبها مستوطن، وما تلاها من تقسيم زماني ومكاني جائر للحرم. هذه الأحداث ليست مجرد سياق سياسي، بل هي جزء من الذاكرة الجمعية الفلسطينية للمكان. الرواية الفلسطينية هنا تصبح رواية مقاومة للتهويد؛ فالحرم الذي كان يجمع المسلمين والمسيحيين في نسيج واحد، قُسّم بفعل الاحتلال. تمسك أهالي الخليل بدخول الحرم والصلاة فيه، رغم كل العراقيل، هو استمرار لتلك الرابطة العضوية التي استمرت قروناً.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "lhrm-lbrhymy-899e38-section-5",
                title: "خلاصة الرواية",
                draftText: "الحرم الإبراهيمي هو تجسيد حي لشعار \"عيون فلسطينية\". إنه الموقع الذي يُرى من خلاله تاريخ فلسطين كاملاً: كنعاني يبيع أرضه لنبي، روماني يبني سوراً، مسيحيون يقيمون كنيسة، مسلمون يحولونها بحكمة إلى مسجد جامع، وعائلات فلسطينية تحرسه وتخدمه ستة قرون، ثم شعب بأكمله يتمسك به في وجه التقسيم. هذه هي الرواية متعددة الأبعاد التي يجب أن تُروى.\n\nبهذه الروايات الموسعة، تكون صفحة كل موقع في تطبيق \"عيون فلسطينية\" قد تحولت من مجرد \"بطاقة معلومات\" إلى \"فيلم وثائقي مقروء\". يمكن للتطبيق عرضها عبر تقسيم النص الطويل إلى بطاقات قابلة للطي (Expansion Tiles) تحت كل عصر، مع إبراز الشهادات الشفوية والاقتباسات من المصادر كمربعات مميزة بصرياً، ليشعر المستخدم أنه يغوص في تاريخ الموقع طبقة تلو الأخرى.\n\nاعتمد ذلك\n\nتم الاعتماد. سأبني على هذه المنهجية في الرواية التاريخية الموسعة لكل موقع يتم توثيقه في مشروع \"عيون فلسطينية\".\n\nالمنهجية المعتمدة للرواية الفلسطينية الموثّقة\n\nالمبادئ الأساسية\n\nالسرد المتعدد الأبعاد: لا نكتفي بسرد الأحداث السياسية، بل نغطي:\n\nالجانب الهندسي والمعماري\n\nالجانب الاجتماعي والاقتصادي (الأوقاف، الحرف، العائلات)\n\nالجانب الديني والروحي\n\nالجانب الإداري والقانوني (السجلات، الحقوق)\n\nالذاكرة الشفوية والتقاليد الشعبية\n\nالنزاعات الحديثة والتهديدات المعاصرة\n\nالتوثيق بالمصدر في المتن: كل معلومة رئيسية تُنسب لمصدرها داخل النص، وليس فقط في نهايته.\n\nالرواية المضادة: نقدم الرواية الفلسطينية التي تصحح التحريفات والمزاعم الإسرائيلية، دون أن نقع في الخطاب الدعائي. نعتمد على الوثائق والأدلة.\n\nالاستمرارية التاريخية: نظهر أن الموقع لم يكن \"ميتاً\" بين عصر وآخر، بل استمر استخدامه وإدارته من قبل السكان المحليين عبر كل العصور.\n\nتطبيق المنهجية على جميع المواقع\n\nسأبدأ الآن بتوسيع الروايات لباقي المواقع الرئيسية في المصفوفة، بنفس العمق الذي قدمناه لبرك سليمان والحرم الإبراهيمي. سأقدمها تباعاً:",
                status: ContentReviewStatus.sourceReview,
