                title: "التخطيط العمراني",
                draftText: "البلدة القديمة للخليل ليست مجرد مجموعة بيوت، بل هي كائن حي عمراني. شوارعها الضيقة المتعرجة (الأزقة) صُممت عمداً لتوفير الظل وتوجيه الرياح. الحارات الرئيسية هي: حارة الشيخ (حول الحرم)، حارة المشارقة (نسبة للمهاجرين من المشرق)، حارة باب الزاوية، وحارة الأكراد. لكل حارة هويتها ومسجدها وساحتها الخاصة (الحوش). الرواية المحلية تروي أن الأزقة كانت تُغلق ليلاً ببوابات خشبية للأمان، وكان لكل حارة شيخ يحل النزاعات.",
