                title: "خان شاهين",
                draftText: "في قلب البلدة القديمة، يقع خان شاهين، وهو خان تجاري ضخم بناه المماليك وجدده العثمانيون. كان يستقبل قوافل التجار القادمين من مصر والشام، وفيه غرف للإقامة ومخازن للبضائع وإسطبلات للخيل. اليوم، الخان مهمل جزئياً، لكنه يظل شاهداً على دور الخليل كمحطة تجارية رئيسية.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-lkhlyl-lqdym-6b6c5a-section-3",
                title: "أسواق الخليل التقليدية",
                draftText: "سوق العنب، سوق الخضار، سوق الصاغة (الذهب)... هذه الأسواق متخصصة ومتقابلة. ما يميز الرواية الفلسطينية هنا هو نظام \"الحسبة\" الذي كان يراقب الأسعار والموازين ويمنع الغش. سجلات المحكمة الشرعية تحوي عشرات القضايا ضد تجار خالفوا الأوزان، مما يدل على رقابة صارمة. (مصدر: \"الخليل: تاريخ وحضارة\" – د. عدنان أبو تبانه).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-lkhlyl-lqdym-6b6c5a-section-4",
                title: "التهديدات المعاصرة",
                draftText: "منذ احتلال 1967، وخاصة بعد إنشاء مستوطنة \"تل رميدة\" في قلب المدينة، تتعرض البلدة القديمة لضغوط هائلة. المستوطنون يحتلون البيوت، والحواجز العسكرية تقطع الأزقة، والتجار يهجرون الأسواق. الرواية الفلسطينية اليوم هي رواية صمود؛ لجنة إعمار الخليل تقوم بترميم البيوت القديمة، والعائلات الخليلية تصر على البقاء رغم المضايقات. كل بيت يُرمم هو تحدٍ للاحتلال. (مصدر: تقارير لجنة إعمار الخليل، مؤسسة أريج).",
