                title: "الموقع والاكتشاف",
                draftText: "تل الرميدة هو تلة أثرية تقع في الجانب الشمالي الغربي من البلدة القديمة للخليل. هو موقع مدينة الخليل القديمة (الكنعانية والإسرائيلية). الحفريات الأثرية التي قامت بها بعثات أمريكية وفلسطينية كشفت عن طبقات استيطانية تعود للألف الثالث قبل الميلاد (العصر البرونزي المبكر). الرواية الفلسطينية تعتز بهذا الموقع لأنه يثبت أن الخليل مدينة كنعانية عربية في أصلها، عمرها أكثر من 5000 عام.",
                status: ContentReviewStatus.sourceReview,
