                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "tl-lrmyd-63c0ba-section-2",
                title: "البوابات والأسوار",
                draftText: "أهم ما كُشف في تل الرميدة هو بوابة المدينة الكنعانية الضخمة وبقايا السور. هذه البوابة تشبه بوابات مدن كنعانية أخرى مثل تل الجزر وتل مجدو، مما يؤكد وحدة الحضارة الكنعانية في فلسطين. الرواية المضادة ترفض الادعاءات الإسرائيلية التي تحاول حصر تاريخ التل في الحقبة التوراتية فقط؛ فالطبقات الكنعانية هي الأقدم والأكثر سمكاً.",
                status: ContentReviewStatus.sourceReview,
