                title: "النبع المقدس",
                draftText: "قرب التل، تقع \"عين جديجة\" (أو عين سارة)، وهي نبع ماء قديم يرجح أنه كان مركز العبادة الكنعاني المرتبط بالمدينة. المياه كانت مقدسة، والمدينة قامت حولها.",
