                title: "الصراع على التل",
                draftText: "اليوم، تل الرميدة هو بؤرة استيطانية. أقام المستوطنون الإسرائيليون بؤرة استيطانية فوق التل الأثري نفسه، وهو انتهاك صارخ للقانون الدولي. الحفريات التي يقومون بها مشبوهة، ويُعتقد أنها تهدف للعثور على أي أثر \"يهودي\" لتبرير وجودهم، مع إهمال الطبقات الكنعانية والإسلامية. (مصدر: تقارير دائرة الآثار الفلسطينية، \"الخليل عبر العصور\" – جامعة الخليل).",
