                draftText: "دورا هي أكبر بلدات محافظة الخليل، تقع على هضبة مرتفعة جنوب غرب الخليل. اسمها مشتق من \"أدورايم\" الكنعانية، وتعني \"المساكن\". اشتهرت دورا منذ القدم بكروم العنب التي تحيط بها، وصناعة الدبس (دبس العنب) التي ما زالت حرفة تقليدية فيها.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "khrb-lnby-nwh-c9ac72-section-2",
                title: "خربة النبي نوح",
                draftText: "قرب دورا، تقع خربة النبي نوح، وهي موقع أثري يضم مقاماً منسوباً للنبي نوح عليه السلام. الرواية المحلية تروي أن نوحاً دُفن هنا، وهناك روايات أخرى تذكر دفنه في العراق أو تركيا. بغض النظر عن صحة الدفن، فإن وجود مقام بهذا الاسم يؤكد أن الذاكرة الشعبية الفلسطينية ربطت هذه الأرض بقصص الأنبياء. المقام مبني بالحجر الكلسي الأبيض، وله قبة بسيطة. كان أهالي دورا يزورونه في المواسم ويقيمون عنده الذبائح والنذور. (مصدر: \"المقامات الدينية في الخليل\" – معهد أريج، شهادات شفوية من أهالي دورا).",
