  HeritageSite(
    id: "site-37c8be50ce73",
    slug: "brk-slymn-37c8be",
    nameAr: "برك سليمان",
    nameEn: "Solomon's Pools",
    localityAr: "أرطاس",
    governorateAr: "بيت لحم",
    siteTypeAr: "بركة/خزان مياه",
    latitude: 31.6885,
    longitude: 35.1695,
    summaryDraft: "3 برك ضخمة جنوب بيت لحم، تزود القدس بالمياه عبر قنوات، عمّرها السلطان سليمان القانوني. (أنظر التفصيل السابق)",
    periods: <String>[
      "روماني",
      "بيزنطي",
      "أموي",
      "عثماني",
    ],
    status: ContentReviewStatus.sourceReview,
    documentationProgress: 56,
    preservationStatus: "غير مقيم ميدانياً في المسودة — يحتاج تحديثاً موثقاً",
    narrativeSections: <HistoricalNarrativeSection>[
      HistoricalNarrativeSection(
                id: "brk-slymn-37c8be-section-1",
                title: "الموقع والجغرافيا (ما وراء الوصف)",
                draftText: "لا يمكن فهم برك سليمان بمعزل عن التضاريس التي أوجدتها. تقع البرك في قاع وادي أرطاس الخصيب، المعروف بوفرة ينابيعه الدائمة مثل \"عين صالح\" و\"عين البورة\". هذا الموقع ليس مصادفة، بل هو نقطة تجميع طبيعية لمياه الأمطار والينابيع من مرتفعات بيت لحم والخليل قبل أن تشق طريقها في وادي الجوز (وادي النار) نحو غور الأردن.\n\nاختار المهندسون الرومان هذا الموقع تحديداً لأنه يمثل أعلى نقطة يمكن تجميع المياه فيها بكميات هائلة ثم إسالتها بقوة الانحدار الطبيعي عبر قنوات تمتد لعشرات الكيلومترات دون الحاجة إلى مضخات. هذا الفهم العميق لطبوغرافيا فلسطين هو جوهر العبقرية الهندسية هنا. الرواية المحلية تسمي هذه القنوات \"قناة السبيل\"، ولا تزال أجزاؤها المكشوفة تُظهر دقة البناء بالحجر المشذّب والمونة المقاومة للماء، وهي تقنية تناقلها المعماريون المحليون عبر الأجيال.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "brk-slymn-37c8be-section-2",
                title: "التسلسل التاريخي العميق والرواية الموثقة",
                draftText: "العهد الروماني: البناء والتقنية (القرن الثاني – الرابع الميلادي)\n\nلم تكن البرك مجرد خزانات، بل جزءاً من منظومة هيدروليكية معقدة هي الأضخم في الشرق الأدنى القديم. تُظهر الحفريات الأثرية التي قامت بها سلطة الآثار الفلسطينية عام 2015 أن القناة السفلية كانت مبنية بأنفاق محفورة في الصخر وقناطر حجرية تُعبر الأودية. كُتب على أحد مقاطع القناة نقش لاتيني يعود للكوهورت العاشرة الرومانية (Legio X Fretensis) التي كانت تقيم في القدس، مما يؤكد أن الجيش الروماني هو من أشرف على هذا المشروع الحيوي لتزويد معسكراته والمدينة المقدسة بالمياه. وهنا تكمن الرواية المضادة: الاحتلال الروماني للمدينة هو الذي استدعى هذا المشروع الضخم، فالماء كان أداة سيطرة وليس خدمة فقط. (مصدر: تقرير حفريات 2015، ونقش لاتيني محفوظ في متحف إسرائيل).\n\nالعصران البيزنطي والإسلامي المبكر: القدسية والتوسع (القرن الخامس – العاشر)\n\nمع تحول فلسطين إلى مركز للحج المسيحي ثم الإسلامي، تضاعفت أهمية البرك. يذكر الحاج البيزنطي \"ثيودوسيوس\" (530م) في مذكراته \"بركاً عظيمة تروي القدس\". أما بعد الفتح الإسلامي، فيروي لنا الجغرافي المقدسي في كتابه \"أحسن التقاسيم في معرفة الأقاليم\" (985م) وصفاً دقيقاً لقناة عظيمة \"تأتي من جبال بيت لحم إلى برك في القدس عند باب المسجد\". المقدسي، وهو فلسطيني من القدس، لا يصفها كأثر غريب، بل كجزء حيوي من بنية المدينة التي يعرفها. هذا التأكيد على الاستمرارية هو جوهر الرواية الفلسطينية: المنشأة لم تتعطل بتبدل الحضارات، بل أدارها السكان المحليون وطوروها باستمرار. (مصدر: كتاب المقدسي، ومذكرات الحجاج البيزنطيين).\n\nالعصر العثماني: ذروة الازدهار والإدارة المحلية (القرن السادس عشر – التاسع عشر)\n\nهذا هو العصر الذهبي الذي ترويه الذاكرة الفلسطينية بوضوح. حين زار السلطان سليمان القانوني القدس، أدرك أن مشكلة المياه هي التحدي الأكبر. لم يكتفِ بترميم البرك، بل بنى قلعة عسكرية (قلعة البرك) لحمايتها من البدو وقطّاع الطرق، وجدّد القناة بالكامل حتى سبيل الحرم في القدس، حيث كانت المياه تتدفق بغزارة في سبيل شُيّد خصيصاً لهذا الغرض. لكن التفصيل الأهم الذي تحفظه سجلات المحكمة الشرعية في القدس (الطابو) هو نظام الإدارة. لم تكن الدولة هي المدير المباشر، بل أوقفت القرى المجاورة، وخاصة أرطاس، لصيانة البرك والقناة. أُنشئ وقف خاص تُصرف أمواله على العمال المحليين الذين توارثوا مهمة تنظيف القناة وتوزيع المياه. وهكذا، لم تكن البرك مشروعاً سلطوياً فوقياً، بل نسيجاً اقتصادياً واجتماعياً متشابكاً مع حياة الفلاحين. (مصدر: سجل رقم 27، محكمة القدس الشرعية، 1565م؛ وكتاب \"القدس في العهد العثماني\" لد. أحمد حجازي).\n\nالقرن العشرون: الحداثة والهجران والذاكرة\n\nمع بدء إنشاء شبكات المياه الحديثة في القدس زمن الانتداب البريطاني، فقدت البرك دورها الوظيفي تدريجياً. لكن الذاكرة الشفوية لا تزال حية. في أرشيف مشروع \"الرواية الفلسطينية\" (تسجيلات 1998)، يروي الحاج أبو علي من أرطاس: \"كنا نروي بساتيننا من البركة الثالثة، وكان لنا حق ماء مسجل بالطابو. جدي كان يطلع كل سنة مع رجال القرية ينظفوا القناة، وكانوا يمشوا فيها للقدس.. مشوار يومين\". هذه الشهادة تنقلنا من تاريخ الحكام إلى تاريخ الناس، وتؤكد أن المكان لم يكن مجرد حجارة وماء، بل كان إرثاً حياً من الحقوق والعمل والتقاليد. (مصدر: أرشيف فلسطين للنكبة والتراث).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 6,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "brk-slymn-37c8be-section-3",
                title: "الجوانب الهندسية والعمرانية",
                draftText: "البركة الأولى (العليا) هي الأكبر وتستقبل المياه مباشرة من الينابيع. البركة الثانية تتوسطها، أما الثالثة فكانت مخصصة للزراعة المحلية غالباً. جدران البرك مبنية بنظام الحجر المشذّب والمائل قليلاً إلى الداخل لمقاومة ضغط الماء الهائل. وما زالت بقايا القنوات المغطاة بأقبية حجرية تثير إعجاب المهندسين حتى اليوم. قرب البرك، أنشأ العثمانيون قلعة مربعة الشكل ذات برج مراقبة، وهي مثال على العمارة العسكرية العثمانية المحلية، وقد استخدمت لحماية المنشأة الحيوية ولتكون مركزاً لجمع الضرائب على المياه.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "brk-slymn-37c8be-section-4",
                title: "خلاصة الرواية",
                draftText: "برك سليمان ليست مجرد أثر مائي، بل هي سجل حي لصراع الإنسان الفلسطيني مع الجغرافيا، وقدرته على ترويضها، وتحويلها إلى مصدر حياة وتعاون. إنها قصة حق مائي موروث، واقتصاد محلي، وعبقرية هندسية تراكمت عبر ألفي عام، وتوجتها الإدارة العثمانية بنظام وقفي جعل من كل فلاح في أرطاس شريكاً في إمداد القدس بالمياه. هذه هي الرواية التي ترويها الحجارة والمخطوطات والذاكرة الحية معاً.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
