                draftText: "يقع دير الجنة في بلدة الخضر، غرب بيت لحم. اسم البلدة \"الخضر\" مشتق من الخضر (القديس جاورجيوس في التقاليد المسيحية الشرقية، أو النبي إلياس/الخضر في التقاليد الإسلامية). الدير هو نموذج حي للتداخل الديني الفلسطيني: كنيسة للقديس جاورجيوس يزورها المسيحيون، ومقام للخضر يزوره المسلمون، في نفس البناء.",
