                draftText: "بحسب التقاليد المسيحية، جاورجيوس كان جندياً رومانياً فلسطينياً من اللد، استشهد في اضطهاد الإمبراطور دقلديانوس (303م). وبحسب التقاليد الإسلامية، الخضر هو \"العبد الصالح\" الذي ذكره القرآن دون اسم، وهو نبي أو ولي حي خالد. الشخصيتان اندمجتا في الذاكرة الشعبية الفلسطينية في شخصية واحدة: فارس مقدس يركب حصاناً ويحارب الشر وينصر المظلومين.",
