      HistoricalNarrativeSection(
                id: "dyr-ljn-lkhdr-f97aa9-section-3",
                title: "الدير والمقام",
                draftText: "الكنيسة الحالية بُنيت في القرن 17، لكن الموقع أقدم. في ساحة الدير، بئر ماء عميقة يعتقد الزوار أنها مقدسة وتشفي الأمراض. المسلمون يزورون المكان لتقديم النذور وإشعال الشموع، تماماً كما يفعل المسيحيون. هذا التداخل ليس توفيقاً لاهوتياً مصطنعاً، بل هو تعبير عضوي عن التدين الشعبي الفلسطيني الذي يوحد ولا يفرق. (مصدر: \"الأولياء والمقامات في فلسطين\" – د. شريف كناعنة، \"القديس جاورجيوس في التراث الفلسطيني\" – د. فيرا سمعان).",
