                draftText: "يقع دير مار سابا في وادي قدرون (وادي النار) على بُعد 15 كيلومتراً شرق بيت لحم، في عمق برية القدس القاحلة. الدير معلق على حافة جرف صخري عمودي، يشبه عش النسر. الوصول إليه كان يتم بحبل وبكرة حتى العصر الحديث. هذا الموقع المتطرف لم يُختر عبثاً؛ فالنساك الذين بنوه كانوا يبحثون عن العزلة المطلقة والتأمل في الصحراء، حيث لا يصلهم صوت العالم.",
