                title: "المؤسس: القديس سابا",
                draftText: "أسس الدير القديس سابا (439-532م)، وهو راهب كبادوكي (من تركيا الحالية) قدم إلى فلسطين وعاش في برية القدس. جمع حوله مئات الرهبان، وبنى الدير كحصن للنسك والصلاة. سابا كان شخصية قوية؛ قاد وفداً من رهبان فلسطين إلى القسطنطينية للدفاع عن العقيدة الأرثوذكسية أمام الإمبراطور. مات في الدير ودُفن فيه، وما زال جسده محفوظاً في كنيسة الدير حتى اليوم. الرواية المحلية ترى فيه أحد آباء الكنيسة الفلسطينية، رغم أنه لم يولد في فلسطين، لأنه أحبها وعاش ومات فيها.",
