                title: "نظام الحياة في الدير",
                draftText: "دير مار سابا هو دير \"لافرا\"، أي دير نساك متجمعين. الرهبان يعيشون في قلالي (غرف) منحوتة في الصخر، ولا يأكلون اللحم أبداً، ويصومون معظم أيام السنة. النساء ممنوعات من دخول الدير حتى اليوم، باستثناء برج صغير خارج السور يُسمى \"برج النساء\"، حيث يمكن للزائرات المبيت. هذه القوانين الصارمة جعلت من مار سابا أحد أكثر الأديرة تحفظاً في العالم، وهو يمثل استمرارية حية للتقاليد الرهبانية الفلسطينية الباكرة.",
