                draftText: "كان دير مار سابا في القرون الوسطى مركزاً فكرياً. فيه أكبر مكتبة مخطوطات في فلسطين بعد مكتبة دير سانت كاترين في سيناء. العديد من المخطوطات السريانية واليونانية والعربية محفوظة فيه. في القرن 19، اشترت مكتبة روسيا القيصرية مجموعة ضخمة من مخطوطاته (مجموعة مار سابا)، مما أثار جدلاً حول سرقة التراث الفلسطيني. (مصدر: \"مكتبة مار سابا\" – د. يوسف زيدان).",
