                title: "العمارة والهندسة",
                draftText: "هيروديون هو تحفة هندسية. بُني بسكب طبقات من التراب والحجر فوق تل طبيعي صغير حتى وصل ارتفاعه إلى 100 متر. داخل التل الصناعي، حُفرت خزانات مياه ضخمة، وأقبية، ومخازن أسلحة. القصر العلوي كان دائرياً بقطر 63 متراً، بأربعة أبراج (أحدها ما زال قائماً). في أسفل التل، كانت هناك بركة سباحة ضخمة محاطة بالأعمدة، وحدائق، ومبانٍ إدارية. هذا المزيج من الترف والعسكرة يعكس شخصية هيرودس: ملك مهووس بالعظمة والخوف معاً.",
