                title: "الموقع والتأسيس",
                draftText: "تقع كنيسة المهد في قلب مدينة بيت لحم، على بُعد 10 كيلومترات جنوب القدس. بُنيت فوق مغارة طبيعية في صخر بيت لحم الكلسي، يُعتقد أنها شهدت ميلاد السيد المسيح. الكنيسة ليست مجرد موقع أثري، بل هي قلب الهوية المسيحية الفلسطينية وأقدس موقع مسيحي في العالم لا يزال قائماً منذ القرن الرابع الميلادي.",
