              ),
      HistoricalNarrativeSection(
                id: "knys-lmhd-4b15f1-section-2",
                title: "ما قبل الكنيسة: مغارة في حقل الرعاة",
                draftText: "الموقع قبل بناء الكنيسة كان مغارة متواضعة في حقل الرعاة شرقي بيت لحم. الأناجيل تذكر أن مريم ويوسف جاءا من الناصرة إلى بيت لحم لاكتتاب السكان الذي أمر به الإمبراطور الروماني أغسطس، وهناك وُلد المسيح في مغارة لأن \"لم يكن لهما موضع في المنزل\". هذه القصة تجعل من بيت لحم، ومن هذه المغارة بالذات، نقطة ارتكاز للرواية المسيحية كلها. والرواية الفلسطينية المحلية تفتخر بأن الرعاة الذين بشروا بالميلاد هم رعاة فلسطينيون من حقول بيت لحم.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lmhd-4b15f1-section-3",
                title: "البناء البيزنطي: هيلانة وقسطنطين",
                draftText: "عام 326م، زارت القديسة هيلانة والدة الإمبراطور قسطنطين فلسطين، وأمرت ببناء كنيسة فوق المغارة. اكتمل البناء عام 339م. التصميم الأصلي كان بازيليكا ضخمة بفناء مكشوف وأروقة، وفوق المغارة مباشرة بُني مذبح. ما يميز هذه الكنيسة أن مدخلها كان واسعاً، لكنه ضُيق لاحقاً في العصور الوسطى إلى \"باب التواضع\" الحالي الذي لا يدخل منه الزائر إلا منحنياً. الرواية المحلية تقول إن هذا التضييق كان لمنع دخول الفرسان الصليبيين بخيولهم، لكن الأرجح أنه كان لمنع الفرسان المماليك من اقتحامها بخيولهم. على أي حال، \"باب التواضع\" أصبح رمزاً للخشوع والاحترام.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lmhd-4b15f1-section-4",
                title: "العصر الإسلامي: العهدة العمرية والحماية",
                draftText: "بعد الفتح الإسلامي للقدس، حضر الخليفة عمر بن الخطاب إلى بيت لحم. الرواية الفلسطينية تروي أنه دخل الكنيسة وأدركته الصلاة، فصلى في الرواق الجنوبي، وليس في المذبح، احتراماً لقدسية المكان. ثم أعطى للبطريرك صفرونيوس عهداً كتابياً (العهدة العمرية لبيت لحم) يضمن فيه سلامة الكنيسة وأمن المسيحيين. هذا العهد جعل كنيسة المهد محمية إسلامياً طوال القرون. (مصدر: العهدة العمرية، محفوظة في مطرانية الروم الأرثوذكس – القدس).",
