                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lmhd-4b15f1-section-5",
                title: "الصليبيون والمماليك والعثمانيون",
                draftText: "في العصر الصليبي، تُوّج فيها بلدوين الأول ملكاً على مملكة بيت المقدس (1100م). جددها المماليك وأضافوا بعض الزخارف. وفي العصر العثماني، حافظ السلاطين على الامتيازات والوضع الراهن. الكنيسة اليوم تحت رعاية ثلاث طوائف رئيسية: الروم الأرثوذكس، واللاتين الكاثوليك، والأرمن الأرثوذكس.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-lmhd-4b15f1-section-6",
                title: "كنيسة المهد والهوية الوطنية الفلسطينية",
                draftText: "لا يمكن فصل كنيسة المهد عن النضال الفلسطيني. في عام 2002، أثناء الانتفاضة الثانية، حاصر الجيش الإسرائيلي مدينة بيت لحم، ولجأ 39 مقاتلاً فلسطينياً إلى الكنيسة طلباً للحماية. استمر الحصار 39 يوماً، وقُتل خلاله جرسون الكنيسة. هذا الحدث جعل من الكنيسة رمزاً وطنياً للمقاومة والصمود. اليوم، كنيسة المهد مُدرجة على قائمة التراث العالمي لليونسكو، والرئيس الفلسطيني محمود عباس هو من افتتح ترميمها الكبير عام 2018، مما يؤكد أنها تحت السيادة الفلسطينية.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
