                title: "خلاصة الرواية",
                draftText: "كنيسة المهد هي شهادة ميلاد فلسطين المسيحية. هي المكان الذي بدأ فيه الإيمان المسيحي، ومنه انتشر إلى العالم. الرواية الفلسطينية تحرس هذا الإرث، مسلمين ومسيحيين معاً، ضد كل محاولات التهويد والطمس.\n\n(المصادر: \"تاريخ بيت لحم\" – الأب بطرس نجم، \"كنيسة المهد\" – مطرانية الروم الأرثوذكس، ملف اليونسكو لموقع الميلاد، أرشيف بلدية بيت لحم).",
                status: ContentReviewStatus.sourceReview,
