                draftText: "بيرزيت بلدة قديمة تقع على تلة شمال رام الله. اسمها مشتق من \"بئر الزيت\"، مما يدل على شهرتها بزراعة الزيتون منذ القدم. في العصر الروماني والبيزنطي، كانت بيرزيت قرية زراعية مزدهرة تزود القدس بزيت الزيتون.",
