                title: "كنيسة القديس بطرس",
                draftText: "في قلب البلدة القديمة، تقف كنيسة القديس بطرس، وهي بناء حجري ضخم أشبه بقلعة. بُنيت في العصر البيزنطي، ودُمرت في الحروب الصليبية، ثم أعيد بناؤها في القرن 12. ما يميزها هو برج الجرس المحصن، الذي كان يستخدم للمراقبة والدفاع. الكنيسة اليوم تخدم الرعية المسيحية في بيرزيت، وهي دليل على عمق الوجود المسيحي في جبال رام الله.",
                status: ContentReviewStatus.sourceReview,
