                title: "العمارة التقليدية",
                draftText: "البلدة القديمة في بيرزيت محفوظة جيداً، ببيوتها الحجرية المقببة وأزقتها الضيقة. جامعة بيرزيت، التي بدأت كمدرسة صغيرة عام 1924 على يد المرحومة نبيهة ناصر، أصبحت اليوم إحدى أهم الجامعات الفلسطينية، مما جعل بيرزيت مركزاً فكرياً وثقافياً.\n\n(المصادر: \"تراث بيرزيت\" – جامعة بيرزيت، Riwaq).",
