                draftText: "أهم ما في عابود هو معاصر الزيتون الرومانية المحفورة في الصخر. هذه المعاصر، بأحواضها وقنواتها، تثبت أن زراعة الزيتون كانت العمود الفقري لاقتصاد فلسطين منذ 2000 عام. لا تزال بعض هذه المعاصر تُستخدم حتى اليوم، مما يُظهر استمرارية مذهلة في التقاليد الزراعية الفلسطينية. الرواية المحلية تفتخر بأن زيت عابود كان يُصدر إلى روما.",
