                draftText: "في الموقع بقايا ثلاث كنائس بيزنطية بأرضيات فسيفسائية، مما يدل على أن عابود كانت مركزاً مسيحياً مهماً. إحدى هذه الكنائس ما زالت تستخدم للصلاة حتى اليوم، مما يجعلها واحدة من أقدم الكنائس المستخدمة باستمرار في العالم.\n\n(مصادر: SWP, Riwaq, \"الزيت والزيتون في فلسطين\" – د. شريف كناعنة).",
