    status: ContentReviewStatus.sourceReview,
    documentationProgress: 52,
    preservationStatus: "غير مقيم ميدانياً في المسودة — يحتاج تحديثاً موثقاً",
    narrativeSections: <HistoricalNarrativeSection>[
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-1",
                title: "الجغرافيا والتسمية",
                draftText: "تقع نابلس في وادٍ خصب بين جبلي عيبال شمالاً وجرزيم جنوباً. موقعها لم يتغير منذ آلاف السنين؛ فهي تقوم على أنقاض مدينة \"شكيم\" الكنعانية، التي كانت أهم مدينة-دولة في شمال فلسطين في الألف الثاني قبل الميلاد. اسمها الحالي \"نابلس\" مشتق من الاسم الروماني \"نيابوليس\" (المدينة الجديدة) الذي أطلقه الإمبراطور فسبسيان عام 72م بعد تدميره لشكيم القديمة. هذا التراكم في الأسماء – شكيم الكنعانية، نيابوليس الرومانية، نابلس العربية – يختزل تاريخ فلسطين.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-2",
                title: "العصر الكنعاني: شكيم المدينة العاصية",
                draftText: "شكيم كانت مدينة-دولة كنعانية قوية. في رسائل تل العمارنة (القرن 14 ق.م)، يشتكي ملكها \"لبايا\" من هجمات البدو (العبيرو) ويتآمر مع ملوك آخرين ضد السلطة المصرية. هذه الرسائل، المحفوظة في المتحف المصري، تظهر أن المدن الكنعانية كانت دولاً ذات سيادة تتفاوض وتتمرد وتتحالف. الرواية الفلسطينية ترى في لبايا جداً للزعماء الوطنيين، أول مقاوم للهيمنة الإمبراطورية في فلسطين. (مصدر: رسائل تل العمارنة – ترجمة د. أحمد فخري).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-3",
                title: "العصر الروماني: نيابوليس الوثنية",
                draftText: "دمر الرومان شكيم القديمة وأعادوا بناءها على الطراز الروماني الكلاسيكي. بنوا فيها مسرحاً، ومدرجاً، ومعابد (أشهرها معبد زيوس على جبل جرزيم). العملة النابلسية الرومانية تحمل صورة الإمبراطور ومعبد الجبل، مما يدل على أهميتها. الرواية المحلية تذكر أن المسرح الروماني ما زالت بقاياه تحت أحياء نابلس الحديثة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-4",
                title: "العصر الإسلامي: نابلس العربية",
                draftText: "بعد الفتح الإسلامي، أصبحت نابلس مدينة إسلامية عربية. جامع النصر (حوّل من كنيسة صليبية)، وجامع الخضراء، هما من أقدم مساجدها. لكن هوية نابلس الحقيقية تشكلت في العصرين المملوكي والعثماني، حين أصبحت مركزاً تجارياً هائلاً.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-5",
                title: "نابلس العثمانية: مركز التجارة والصابون",
                draftText: "في العصر العثماني (القرن 16-20)، كانت نابلس أغنى مدينة في فلسطين بعد القدس، وربما قبلها. اشتهرت بصناعة الصابون النابلسي المصنوع من زيت الزيتون، وصناعة النسيج، ودباغة الجلود. خاناتها (خان التجار، خان الوكالة) كانت تعج بقوافل الحج والتجارة بين دمشق والقاهرة والحجاز. سجلات المحكمة الشرعية في نابلس تُظهر مجتمعاً تجارياً متقدماً، فيه شركات عائلية، وعقود مضاربة، وتأمين على القوافل. عائلات نابلسية مثل آل عبد الهادي وآل طوقان وآل النمر تحولت إلى قوى سياسية واقتصادية حكمت مناطق واسعة من فلسطين. (مصدر: \"نابلس في العهد العثماني\" – د. بشارة دوماني، سجلات محكمة نابلس الشرعية).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "bld-nbls-lqdym-a9ac19-section-6",
                title: "البلدة القديمة اليوم",
                draftText: "البلدة القديمة في نابلس هي واحدة من أفضل البلدات القديمة المحفوظة في فلسطين، رغم الدمار الذي لحق بها أثناء الاجتياح الإسرائيلي عام 2002. أزقتها الضيقة، وأسواقها المسقوفة، وحماماتها التركية (حمام الشفاء، حمام السمرة)، وكنائسها ومساجدها، ومصابنها (مصابن الصابون) ما زالت تعمل. الرواية الفلسطينية الحية هنا هي رواية إعادة الإعمار؛ فبعد دمار 2002، أعاد النابلسيون بناء أسواقهم وبيوتهم حجراً حجراً.",
