                title: "خلاصة الرواية",
                draftText: "نابلس هي القلب التجاري والاقتصادي لفلسطين عبر العصور. من شكيم المتمردة على فرعون، إلى نيابوليس الرومانية، إلى نابلس العثمانية عاصمة الصابون والتجارة، إلى البلدة القديمة التي تنهض من تحت الركام اليوم، نابلس هي قصة صمود وازدهار لا ينقطع.\n\n(المصادر: \"نابلس: تاريخ وتراث\" – جامعة النجاح الوطنية، Riwaq، سجلات محكمة نابلس الشرعية، \"الصابون النابلسي\" – وزارة الثقافة الفلسطينية).",
