                id: "jbl-jrzym-b6773e-section-1",
                title: "الموقع وقدسية المكان",
                draftText: "جبل جرزيم هو الجبل الجنوبي المطل على نابلس (ارتفاع 881م). بالنسبة للطائفة السامرية، هو أقدس مكان على وجه الأرض، وهو قبلتهم وقبلتهم الحقيقية، وليس القدس. السامريون يؤمنون أن إبراهيم همّ بذبح ابنه إسحق على هذا الجبل (لا على جبل الموريا في القدس كما تؤمن التوراة اليهودية)، وأن يشوع بن نون بنى مذبح بني إسرائيل عليه بعد دخول أرض كنعان، وأن الهيكل الحقيقي كان عليه وليس في القدس.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "jbl-jrzym-b6773e-section-2",
                title: "السامريون: الشعب المضطهد",
                draftText: "السامريون هم أقدم طائفة دينية مستمرة في فلسطين. يزعمون أنهم بقية بني إسرائيل الحقيقيين الذين لم يسبهم الآشوريون عام 722 ق.م، بل بقوا في أرضهم. اليهود يعتبرونهم هراطقة. عددهم اليوم لا يتجاوز 800 شخص، يعيش نصفهم في حارة السامريين على جبل جرزيم في نابلس، ونصفهم الآخر في حولون قرب تل أبيب. الرواية الفلسطينية ترى فيهم أقلية وطنية فلسطينية أصلية، وجزءاً من النسيج الوطني. هم الوحيدون الذين يحملون الجنسيتين الفلسطينية والإسرائيلية، ويتحدثون العربية والعبرية، ويحافظون على لغتهم السامرية القديمة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "jbl-jrzym-b6773e-section-3",
                title: "الآثار على الجبل",
                draftText: "على قمة جرزيم، بقايا معبد سامري قديم دمره المكابيون اليهود في القرن الثاني ق.م، وهو أكبر جرح في الذاكرة السامرية. هناك أيضاً بقايا كنيسة بيزنطية بُنيت فوق المعبد المهدم، وقلعة صغيرة من العصر الأيوبي. في كل عام، يقيم السامريون ذبيحة الفصح على الجبل، وهو احتفال مهيب يجذب الزوار من العالم. الرواية الفلسطينية المحلية تعتبر هذا الاحتفال جزءاً من تراث نابلس. (مصدر: \"السامريون: تاريخ وعقيدة\" – د. حسني دعيس، مقابلات مع كهنة الطائفة السامرية – أرشيف جامعة النجاح).",
