                id: "sbsty-shmrwn-6f6afe-section-1",
                title: "الجغرافيا والتسمية",
                draftText: "تقع سبسطية على تل استراتيجي يطل على سهل خصب، شمال غرب نابلس. اسمها الكنعاني الأصلي \"شمرون\" (أو سامر)، ويعني \"مكان الحراسة\" أو \"البرج\"، مما يعكس وظيفتها الدفاعية منذ البداية. التل محاط بوديان عميقة من ثلاث جهات، مما جعله حصناً طبيعياً. الاسم الحالي \"سبسطية\" هو تحريف للاسم اليوناني \"سيباستي\" الذي أطلقه هيرودس الكبير (القرن الأول ق.م) تكريماً للإمبراطور الروماني أغسطس (سيباستوس باليونانية). هذه الطبقات اللغوية (كنعاني، يوناني، عربي) تختزل تاريخ الموقع وتؤكد أصالته الفلسطينية المتصلة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-2",
                title: "العصر الكنعاني والإسرائيلي: البدايات",
                draftText: "كانت شمرون مدينة-دولة كنعانية في الألف الثاني ق.م. ذكرت في نصوص اللعنات المصرية (القرن 18 ق.م) وفي رسائل تل العمارنة. اشترى الملك عمري (القرن التاسع ق.م) التل من رجل كنعاني اسمه \"شامر\" بمبلغ من الفضة، كما تروي الرواية التوراتية نفسها (سفر الملوك الأول 16:24). وهنا تظهر الرواية المضادة: حتى مملكة السامرة الإسرائيلية لم تنشأ على أرض خالية، بل بُنيت على مدينة كنعانية موجودة، واشترى مؤسسوها الأرض. هذا يؤكد أن الوجود العربي الكنعاني هو الأصل، وما جاء بعده كان طبقة فوقه.\n\nجعلها الملك عمري عاصمته، ووسعها ابنه آخاب الذي بنى \"معبد البعل\" و\"القصر العاجي\". كشفت الحفريات عن مئات القطع العاجية المنحوتة بفخامة، مما يؤكد ثراء المدينة. دمرها الآشوريون عام 722 ق.م وسبوا سكانها. هنا تتبنى الرواية الفلسطينية حقيقة أن \"الأسباط العشرة المفقودة\" لم تكن إلا نخبة حاكمة، أما الفلاحين الكنعانيين (السامريين) فقد بقوا في أرضهم واستمروا يزرعونها. وهذا ما يفسر استمرار الوجود السامري في نابلس حتى اليوم، وهم جزء من النسيج الفلسطيني.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-3",
                title: "العصر الروماني: إعادة التأسيس الهيرودية",
                draftText: "في عام 27 ق.م، منح الإمبراطور أغسطس المدينة لهيرودس الكبير. أعاد هيرودس، المعروف بمشاريعه العمرانية الضخمة، بناءها بالكامل على الطراز الروماني. شيّد:\n\nمعبداً ضخماً للإمبراطور أغسطس على قمة التل (بقاياه ما زالت ظاهرة).\n\nمسرحاً رومانياً يتسع لـ 3000 متفرج، منحوت في سفح التل.\n\nملعباً (استاداً) للألعاب الرياضية.\n\nشوارع مرصوفة بالأعمدة (الكاردو والديكومانوس).\n\nهذا المزيج من المعبد والمسرح هو ما يجعل سبسطية فريدة. الرواية المحلية تسمي المسرح \"المدرج\"، وكان أهالي سبسطية، قبل الاحتلال، يقيمون فيه حفلاتهم وأعراسهم. هذا الاستخدام الشعبي المعاصر للمكان الأثري هو جزء من الرواية الفلسطينية الحية.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 2,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-4",
                title: "العصر البيزنطي: التحول للمسيحية",
                draftText: "مع اعتناق الإمبراطورية المسيحية، تحولت سبسطية إلى مركز أسقفي مهم. تحطم المعبد الروماني وحلّت محله كنيسة بازيليكية. يُعتقد أن رفات القديس يوحنا المعمدان نُقلت إلى هنا، مما جعلها محجة للحجاج. لا تزال بقايا الكنيسة البيزنطية ظاهرة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-5",
                title: "العصر الإسلامي: الاستمرارية",
                draftText: "بعد الفتح الإسلامي، لم تُهجر سبسطية. استمرت كقرية عامرة، وسكنتها قبائل عربية. تعايش المسلمون مع السامريين والمسيحيين فيها. الرواية الشفوية تذكر أن مسجد القرية القديم بُني بجوار الكنيسة البيزنطية دون هدمها.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-6",
                title: "العصر الصليبي: الكاتدرائية والجامع",
                draftText: "في القرن 12، أقام الصليبيون كاتدرائية ضخمة على أنقاض الكنيسة البيزنطية، مكرسة للقديس يوحنا المعمدان. بعد تحرير صلاح الدين للمنطقة، لم تُهدم الكاتدرائية، بل حُوّل جزء منها إلى الجامع الكبير في سبسطية، وظل جزء آخر مقاماً للنبي يحيى (يوحنا المعمدان) يزوره المسلمون والمسيحيون على السواء. هذا التحول السلمي من كنيسة إلى جامع ومقام مشترك هو نموذج نادر للتعايش، تؤكده الرواية الفلسطينية وتفخر به. (مصدر: \"الآثار الصليبية في فلسطين\" – د. يوسف النتشة).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-7",
                title: "العصر الحديث: الإهمال والتهديد",
                draftText: "تقع سبسطية اليوم في المنطقة (ج) الخاضعة للسيطرة الإسرائيلية الكاملة. الرواية الفلسطينية المعاصرة هي رواية معاناة: الموقع الأثري المهمل الذي ينهار، منع الحفائر الفلسطينية فيه، تحويل المنطقة المحيطة إلى مستوطنات، وإغلاق الطرق. كما يروي الباحث د. أسامة حمدان: \"سبسطية متحف مفتوح يضيع أمام أعيننا\".",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "sbsty-shmrwn-6f6afe-section-8",
                title: "خلاصة الرواية",
                draftText: "سبسطية هي فلسطين مصغّرة: كنعانية الأصل، توجها الرومان، احتضنت المسيحية والإسلام، تعايشت فيها الأديان، وتواجه اليوم خطر الطمس. إنقاذ روايتها هو إنقاذ لذاكرة المكان.\n\n(المصادر: كتاب \"سبسطية عبر التاريخ\" – معهد أريج، \"تاريخ فلسطين القديم\" – خالد عوض، سجلات SWP، شهادات سكان سبسطية – أرشيف مركز المعمار الشعبي رواق).",
