                draftText: "يقع مقام النبي يوسف في بلدة بلاطة، على المدخل الشرقي لمدينة نابلس. هو بناء حجري أبيض صغير بقبة خضراء. الرواية الإسلامية تؤكد أن النبي يوسف بن يعقوب دُفن هنا. بينما تذكر التوراة أن عظامه نُقلت من مصر إلى شكيم (بلاطة الحالية) ودُفنت في \"قطعة الحقل التي اشتراها يعقوب\". هذا التطابق النادر بين الروايتين الإسلامية والتوراتية يجعل الموقع ذا أهمية استثنائية.",
