                title: "النزاع الحديث",
                draftText: "بعد اتفاقية أوسلو (1995)، وقع المقام في المنطقة (ب) الخاضعة للسيطرة المدنية الفلسطينية والأمنية الإسرائيلية المشتركة. في عام 2000، مع بدء الانتفاضة الثانية، سيطر الفلسطينيون على المقام لفترة قصيرة، ثم استعادته إسرائيل بالقوة. منذ ذلك الحين، وهو موقع عسكري إسرائيلي مغلق، ويمنع المسلمون من الصلاة فيه إلا بتصاريح خاصة ومرافقة عسكرية، وعادة في ساعات الليل فقط. الرواية الفلسطينية ترى في هذا الإغلاق استمراراً لتهويد الأماكن المقدسة. في عام 2015، أحرق فلسطينيون أجزاء من المقام احتجاجاً، مما أثار موجة إدانة وإعادة ترميم إسرائيلية. اليوم، المقام رمز للصراع على المقدسات في فلسطين.",
