                title: "الموقع والتسمية",
                draftText: "جنين مدينة قديمة في أقصى شمال الضفة الغربية، تطل على مرج ابن عامر (سهل زرعين) الخصب. اسمها مشتق من \"عين جنيم\" الكنعانية (عين الجنائن)، مما يعكس خصوبة الموقع وغزارة مياهه. هي بوابة فلسطين الشمالية، والرابط بين جبال نابلس وسهل مرج ابن عامر وجبال الكرمل.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "qsr-lkyd-fe1e2a-section-2",
                title: "العصر الكنعاني والروماني",
                draftText: "قامت جنين على أنقاض مدينة \"عين جنيم\" الكنعانية. في العصر الروماني، كانت قرية صغيرة تابعة لمدينة سبسطية. لكن أهميتها نمت تدريجياً بسبب موقعها على طريق القوافل بين مصر ودمشق.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "qsr-lkyd-fe1e2a-section-3",
                title: "العصر الإسلامي: جنين العربية",
                draftText: "بعد الفتح الإسلامي، استقرت قبائل عربية في المنطقة. في العصر المملوكي، أصبحت جنين محطة على طريق البريد بين دمشق والقاهرة. بنى المماليك فيها قلعة صغيرة لحماية الطريق. في العصر العثماني، أصبحت مركز ناحية (قضاء) يتبع لواء اللجون. سجلات المحكمة الشرعية في نابلس (التي كانت تتبع لها جنين) تذكر جنين كمركز زراعي ينتج القمح والشعير والسمسم.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "qsr-lkyd-fe1e2a-section-4",
                title: "قصر الكايد: حصن آل عبد الهادي",
                draftText: "في القرن 18-19، حكمت عائلة عبد الهادي النابلسية منطقة جنين. بنوا \"قصر الكايد\" في قلب جنين، وهو قلعة صغيرة بأسوار عالية وأبراج للمراقبة. القصر كان مركزاً للإدارة وجباية الضرائب. الرواية المحلية تروي قصصاً عن صراعات آل عبد الهادي مع آل طوقان في نابلس، وعن تحالفهم مع ظاهر العمر حاكم عكا. القصر اليوم مهجور جزئياً لكنه ما زال قائماً. (مصدر: \"العائلات الإقطاعية في فلسطين\" – د. بشارة دوماني، Riwaq).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "qsr-lkyd-fe1e2a-section-5",
                title: "جنين الحديثة: المخيم والمقاومة",
                draftText: "بعد نكبة 1948، أُقيم مخيم جنين للاجئين غرب المدينة، وسكنه لاجئون من حيفا والكرمل. تحول المخيم إلى معقل للمقاومة الفلسطينية. في اجتياح 2002 (عملية السور الواقي)، تعرض المخيم لدمار هائل في معركة استمرت عشرة أيام، استشهد فيها 52 فلسطينياً و23 جندياً إسرائيلياً. هذه المعركة جعلت من جنين رمزاً للمقاومة والصمود في الوجدان الفلسطيني. الرواية الحية لجنين اليوم هي رواية إعادة البناء والتحدي.\n\n(المصادر: \"جنين: تاريخ وحضارة\" – د. نمر سرحان، \"مخيم جنين: ذاكرة ومقاومة\" – مركز بديل، شهادات الناجين من معركة 2002).",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
