    narrativeSections: <HistoricalNarrativeSection>[
      HistoricalNarrativeSection(
                id: "knys-brqyn-2c1f6b-section-1",
                title: "الموقع والتأسيس",
                draftText: "تقع كنيسة القديس جاورجيوس (الخضر) في بلدة برقين، غرب جنين. تُعرف ببساطة باسم \"كنيسة برقين\". الرواية الكنسية الفلسطينية تؤكد أنها خامس أقدم كنيسة في العالم، ورابع أقدس موقع مسيحي بعد القدس وبيت لحم والناصرة. بُنيت في القرن الرابع أو الخامس الميلادي، وما زالت تستخدم للصلاة حتى اليوم، مما يجعلها واحدة من أقدم الكنائس المستخدمة باستمرار في العالم.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-brqyn-2c1f6b-section-2",
                title: "معجزة المسيح",
                draftText: "بحسب التقليد المسيحي، مرّ المسيح بقرية برقين في طريقه من الناصرة إلى القدس، وشفى فيها عشرة برص كانوا منعزلين في مغارة خارج القرية. هذه المغارة ما زالت موجودة داخل الكنيسة، وتحولت إلى مزار مقدس. قصة الشفاء هذه (المذكورة في إنجيل لوقا 17:11-19) تجعل من برقين محطة في طريق الآلام، وتضفي على الكنيسة قدسية خاصة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-brqyn-2c1f6b-section-3",
                title: "العمارة والترميم",
                draftText: "الكنيسة مبنية بالحجر الكلسي الأبيض، بتصميم بازيليكي بسيط. جُددت عدة مرات عبر العصور، آخرها ترميم كبير قامت به وزارة السياحة الفلسطينية وبلدية برقين بتمويل دولي. الكنيسة اليوم تخدم الرعية المسيحية الصغيرة في برقين، وتستقبل الحجاج من كل العالم.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "knys-brqyn-2c1f6b-section-4",
                title: "خلاصة الرواية",
                draftText: "كنيسة برقين هي الدليل الحي على أن جذور المسيحية في شمال فلسطين عميقة ومستمرة. إنها تثبت أن فلسطين ليست مجرد أرض الأنبياء، بل هي أيضاً أرض المعجزات والقديسين.\n\n(المصادر: \"دليل كنائس فلسطين\" – مطرانية الروم الأرثوذكس، بلدية برقين، \"طريق الآلام في فلسطين\" – وزارة السياحة).\n\nبهذا أكملت محافظة جنين. سأنتقل إلى محافظة رام الله والبيرة، ثم أواصل بلا توقف حتى نهاية محافظات غزة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
