    status: ContentReviewStatus.sourceReview,
    documentationProgress: 52,
    preservationStatus: "غير مقيم ميدانياً في المسودة — يحتاج تحديثاً موثقاً",
    narrativeSections: <HistoricalNarrativeSection>[
      HistoricalNarrativeSection(
                id: "khrb-brj-l-bd-7a4bd9-section-1",
                title: "سياق محافظة طولكرم",
                draftText: "تقع مدينة طولكرم في السهل الساحلي الفلسطيني، على الحافة الغربية لجبال نابلس، حيث يلتقي السهل بالجبل. اسمها مشتق من \"طور الكرم\" (جبل الكرم)، مما يدل على شهرتها بزراعة الكروم والزيتون منذ القدم. هي بوابة فلسطين على البحر المتوسط، وهمزة الوصل بين الساحل والداخل.\n\nقامت طولكرم على أنقاض بلدة \"بيرات سورقا\" الرومانية (بئر الكروم). كانت محطة على الطريق الروماني بين قيسارية ماريتيما (عاصمة فلسطين الرومانية) ونابلس. في العصر البيزنطي، أصبحت مركزاً زراعياً يزود الساحل بالغلال. بقايا معاصر الزيتون الرومانية المنتشرة حول المدينة تشهد على هذا التاريخ الزراعي العميق.\n\nبعد الفتح الإسلامي، استقرت قبائل عربية في المنطقة، وتحول الاسم إلى \"طور الكرم\". في العصر المملوكي، أصبحت طولكرم مركز ناحية إدارية. لكن ازدهارها الحقيقي كان في العصر العثماني، حين أصبحت مركزاً لتجارة الحبوب والزيت بين جبال نابلس وموانئ يافا وحيفا. سجلات المحكمة الشرعية في نابلس تذكر تجاراً من طولكرم كانوا يصدرون زيت الزيتون إلى مصر وفرنسا. (مصدر: \"طولكرم: تاريخ وتراث\" – بلدية طولكرم).\n\nفي الانتداب البريطاني، أقام البريطانيون معسكراً كبيراً في طولكرم (معسكر نور الشام)، تحول بعد النكبة إلى مخيم للاجئين (مخيم طولكرم). المدينة اليوم هي مركز محافظة طولكرم، وتعاني من جدار الفصل العنصري الذي يعزلها عن أراضيها الزراعية في السهل الساحلي. الرواية الفلسطينية المعاصرة هنا هي رواية فلاحين فصلوا عن أرضهم بجدار إسمنتي.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 3,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "khrb-brj-l-bd-7a4bd9-section-2",
                title: "الموقع والبناء",
                draftText: "تقع خربة برج العبد على تلة مشرفة قرب بلدة عنبتا، شرق طولكرم. هي بقايا برج حجري ضخم وقلعة صغيرة، بُنيت في العصر الصليبي (القرن 12) كجزء من سلسلة حصون كانت تحمي طريق القوافل بين الساحل ونابلس. البرج مبني بالحجر الكلسي المشذب، وله أساسات ضخمة ما زالت ظاهرة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "khrb-brj-l-bd-7a4bd9-section-3",
                title: "الوظيفة العسكرية والتجارية",
                draftText: "لم يكن البرج مجرد نقطة عسكرية، بل كان أيضاً محطة جباية للضرائب (رسوم المرور) على القوافل التجارية. في العصر المملوكي، جُدد البرج وأُضيفت إليه تحصينات. الرواية المحلية تسميه \"برج العبد\" نسبة إلى أمير مملوكي أو جندي مجهول. البرج اليوم مهمل، لكنه يظل شاهداً على أهمية المنطقة كمعبر استراتيجي.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "khrb-brj-l-bd-7a4bd9-section-4",
                title: "الرواية الشفوية",
                draftText: "أهالي عنبتا يروون أن البرج كان يستخدم في العصر العثماني كمركز للمراقبة ضد غارات البدو، وفيه بئر ماء عميقة كان يلجأ إليها السكان أثناء الهجمات. هذه الرواية الشفوية تدمج بين التاريخ العسكري والذاكرة الشعبية. (مصدر: \"قلاع شمال فلسطين\" – معهد أريج).",
