                draftText: "معاصر جبع هي من أكبر المعاصر الرومانية في شمال فلسطين. أحواضها الحجرية الضخمة وقنواتها المتقنة تدل على إنتاج زيت زيتون بكميات تجارية ضخمة. الزيت كان يُصدر إلى روما والقسطنطينية. الرواية الفلسطينية ترى في هذه المعاصر دليلاً على أن زراعة الزيتون كانت ولا تزال العمود الفقري لاقتصاد فلسطين، وأن الفلاح الفلسطيني هو وريث هذه الحضارة الزراعية مباشرة. (مصدر: SWP, \"الزيت والزيتون في فلسطين\" – د. شريف كناعنة).",
