                draftText: "الرواية الفلسطينية الحديثة لقلقيلية هي رواية مأساوية. بعد عام 2002، أحاطت إسرائيل المدينة بجدار الفصل العنصري من ثلاث جهات، تاركة منفذاً واحداً يسيطر عليه حاجز عسكري. قلقيلية تحولت إلى سجن كبير، وعُزلت عن أراضيها الزراعية وعن محيطها الفلسطيني. هذه الرواية الحية تطغى على كل تاريخها القديم، وتجعل من قلقيلية رمزاً لمعاناة المدن الفلسطينية المحاصرة. (مصدر: تقارير \"أوقفوا الجدار\" – مؤسسة الحق، بلدية قلقيلية).",
