                draftText: "كان أهالي عزون والقرى المجاورة يزورون المقام في المواسم، ويقيمون عنده الذبائح والنذور، خاصة لطلب الشفاء من الأمراض. النساء كن يربطن أقمشة خضراء على شبابيك المقام للتبرك. هذه الممارسات، التي تراجع كثيراً في العقود الأخيرة، هي جزء من التراث الديني الشعبي الفلسطيني الذي يدمج بين التصوف والإيمان الشعبي. (مصدر: \"مقامات شمال فلسطين\" – أريج، شهادات شفوية من أهالي عزون).",
