                draftText: "بقايا الدير البيزنطي (أرضيات فسيفساء، معاصر، آبار) ما زالت ظاهرة في القرية. بعد الفتح الإسلامي، تحول الدير تدريجياً إلى قرية زراعية. لكن الأهم أن مسجد القرية الحالي بُني فوق موقع الدير القديم، في استمرارية للمكان المقدس. هذا التحول السلمي من دير إلى مسجد وقرية هو نموذج مصغر لتاريخ فلسطين. (مصدر: SWP, Riwaq).",
