                title: "العمارة والتحصينات",
                draftText: "أهم ما كُشف في تل الفارعة هو بوابة المدينة الكنعانية الضخمة، والسور الحجري، والمعبد الكنعاني، والبيوت السكنية المنظمة. التخطيط العمراني المتقدم يدل على مجتمع حضري منظم. الرواية الفلسطينية ترى في هذه المدينة دليلاً على أن فلسطين كانت أرض حضارة ومدنية قبل آلاف السنين من وصول العبرانيين. (مصدر: \"حفريات تل الفارعة\" – جامعة النجاح، تقارير البعثة الفرنسية).",
