                title: "أريحا الكنعانية: البرج والأسوار",
                draftText: "أروع ما في تل السلطان هو البرج الدائري الضخم (ارتفاعه 8.5 متر) والسور الحجري الذي يعود للألف التاسع قبل الميلاد. هذا البرج هو أقدم بناء حجري بهذا الحجم في العالم. بناه سكان أريحا الأوائل، وهم مجتمع زراعي متقدم سبق الأسر المصرية بآلاف السنين. الرواية الفلسطينية تفخر بأن أجدادها هم بناة أول مدينة في التاريخ. (مصدر: \"أريحا: أقدم مدينة في العالم\" – كاثلين كينيون، تقارير دائرة الآثار الفلسطينية، اليونسكو).",
