                id: "tl-lsltn-ryh-lqdym-a86fc0-section-3",
                title: "الرواية المضادة: قصة يوشع",
                draftText: "التوراة تروي أن يشوع بن نون دمر أسوار أريحا ونفخ في الأبواق. الرواية الفلسطينية تصحح: طبقات تل السلطان الأثرية لا تظهر أي دمار مفاجئ في العصر البرونزي المتأخر (زمن يشوع المفترض). المدينة كانت مهجورة في ذلك الوقت أصلاً، أو دمرت قبل ذلك بقرون. قصة يشوع هي أسطورة توراتية لا يدعمها علم الآثار. أريحا الكنعانية استمرت كمدينة فلسطينية متصلة الحضارة، لا كمدينة دمرها غزاة.",
