                draftText: "بُني الدير الحالي في القرن 19 على أنقاض دير بيزنطي أقدم. لكن المغارة التي صام فيها المسيح موجودة في قلب الجبل منذ الأزل. الدير مبني على مصاطب صخرية، وكأنه متشبث بالجبل. الوصول إليه كان يتم بحبل حتى منتصف القرن 20. اليوم، تلفريك سياحي يصعد الزوار إلى قمة الجبل.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "dyr-qrntl-cc4465-section-3",
                title: "النساك والمتوحدون",
                draftText: "منذ القرن الرابع، سكن النساك المسيحيون كهوف هذا الجبل. عاشوا حياة تقشف مطلق، يأكلون الأعشاب ويصلون طوال النهار. دير قرنطل هو أحد آخر الأدلة على تقليد \"الصحراء المقدسة\" في فلسطين، حيث كان النساك يتحدون الجسد والطبيعة للوصول إلى الله. الرواية الفلسطينية المحلية تحترم هذا الإرث النسكي، وتعتبره جزءاً من تراث وادي الأردن. (مصدر: \"دليل الأديرة الفلسطينية\" – مطرانية الروم الأرثوذكس).",
