                title: "الموقع والبناء",
                draftText: "وادي القلط هو وادٍ صخري عميق يصل بين القدس وأريحا. على جدرانه الشمالية، بنى الرومان قناة مائية معلقة (أكوا دكت) تنقل مياه عين فاره وعين القلط إلى أريحا وقصر هشام. القناة محفورة في الصخر ومبنية على قناطر في الأجزاء المنحدرة.",
                status: ContentReviewStatus.sourceReview,
                evidenceNote: 'النص مستخرج من المسودة المرجعية ويحتاج تفكيكاً إلى ادعاءات وربطاً بمصادر وصفحات قابلة للتحقق.',
                claimCount: 1,
                citedClaimCount: 0,
              ),
      HistoricalNarrativeSection(
                id: "qn-wdy-lqlt-7551f6-section-2",
                title: "العبقرية الهندسية",
                draftText: "ما يجعل القناة معجزة هو انحدارها المدروس بدقة (0.5%)، مما يسمح للماء بالجريان بقوة دون أن يتوقف أو يفيض. بُنيت في القرن الأول أو الثاني الميلادي، وجُددت في العصر الأموي. لا تزال أجزاء منها تستخدم حتى اليوم لري بساتين أريحا. هذه الاستمرارية هي دليل حي على عبقرية الهندسة الرومانية والأموية. (مصدر: \"أنظمة المياه\" – م. ناصر الدين).\n\nقطاع غزة",
