                draftText: "ازدهرت غزة في العصر الروماني كمركز تجاري وثقافي. كانت تمتلك مدرسة بلاغة شهيرة. في العصر البيزنطي، أصبحت أسقفية مهمة، وشُيدت فيها كنائس ضخمة (كنيسة القديس برفيريوس). فتحها عمرو بن العاص في القرن السابع، واستمرت كمدينة إسلامية عربية.",
