                draftText: "في العصر المملوكي، كانت غزة عاصمة نيابة (ولاية) تمتد من رفح إلى قيسارية. بنى المماليك فيها المسجد العمري الكبير، وقلعة برقوق، وخان يونس. في العصر العثماني، أصبحت غزة قاعدة للحجاج المصريين. اشتهرت بتجارة الحبوب والقطن والصابون.",
